// Auto-generated movement artwork data URLs for VerbDrops.
// Source images are compressed to WebP for Cloudflare-friendly delivery.
// Keep this file text-only so GitHub connector can commit it without binary upload.

export const VERB_DROP_MOVEMENT_ARTWORK: Record<string, string> = {
  "ללכת": "data:image/webp;base64,",
};

export function getVerbDropArtworkSrc(infinitiveHebrew: string): string | undefined {
  return VERB_DROP_MOVEMENT_ARTWORK[infinitiveHebrew];
}
